"""Stable future adapter boundaries; no real providers are registered."""

from typing import Protocol

from .errors import FrameworkError
from .security import Secret


class InstallerProvider(Protocol):
    def metadata(self, version: str, platform: dict) -> dict: ...
    def download(self, metadata: dict) -> str: ...
    def verify(self, path: str, metadata: dict) -> bool: ...
    def install(self, path: str) -> None: ...
    def installed_version(self) -> str | None: ...


class RegistrationProvider(Protocol):
    def register(self, desired: dict, secret: Secret) -> None: ...
    def verify(self, identity: dict) -> dict: ...
    def classify_failure(self, evidence: dict) -> str: ...


class HealthProvider(Protocol):
    def check(self, identity: dict, deadline: float) -> dict: ...


class SecretProvider(Protocol):
    def resolve(self, reference: dict) -> Secret: ...
    def clear(self) -> None: ...


class ArtifactProvider(Protocol):
    def obtain(self, reference: dict) -> str: ...


class MutationProvider(Protocol):
    def read(self, path: str) -> dict: ...
    def backup(self, current: dict) -> str: ...
    def diff(self, current: dict, desired: dict) -> dict: ...
    def apply(self, changes: dict) -> None: ...
    def validate(self, path: str) -> bool: ...
    def restore(self, backup: str) -> None: ...


def require_runtime_provider(kind):
    if kind in {"registration", "health"}:
        raise FrameworkError("BLOCKED_BY_PHASE_0_DEPENDENCY")
    raise FrameworkError("NOT_IMPLEMENTED")
